'use strict';
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = n => `<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const money = v => '₹' + Number(v).toLocaleString('en-IN', {maximumFractionDigits:2});
const compact = v => v >= 100000 ? '₹' + (v/100000).toFixed(2) + 'L' : money(v);
const btn = (text, action, cls = '', attrs = '') => `<button class="button ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const pill = (text, cls = '') => `<span class="tag ${cls}">${esc(text)}</span>`;
const empty = (text, ico = 'inbox') => `<div class="empty">${icon(ico)}${esc(text)}</div>`;
const initials = name => name.split(' ').slice(0,2).map(n=>n[0]).join('').toUpperCase();
const services = [
 {id:'registration',name:'Company registration',category:'Legal & setup',icon:'brief',tone:'gold',desc:'Pvt Ltd, LLP, and OPC incorporation support. Build your business on a strong foundation.',items:['Entity selection and requirements','Document collection','Incorporation milestones']},
 {id:'gst',name:'Accounting & GST',category:'Finance',icon:'chart',tone:'',desc:'Ongoing bookkeeping, GST, and TDS support from the professionals behind your business.',items:['Bookkeeping requirements','GST and TDS support','Financial reporting scope']},
 {id:'brand',name:'Brand identity',category:'Design & growth',icon:'design',tone:'rose',desc:'A considered identity, from your first logo to the guidelines that bring your brand together.',items:['Discovery and creative direction','Identity exploration','Brand guidelines and files']},
 {id:'web',name:'Website development',category:'Technology',icon:'code',tone:'blue',desc:'Business websites and digital experiences built around your goals and your customers.',items:['Requirements and page structure','Design and development','Review and handover']},
 {id:'trademark',name:'Trademark support',category:'Legal & setup',icon:'shield',tone:'gold',desc:'Get guidance on protecting the identity you are building, with trademark filing support.',items:['Classification and scope','Filing support','Application tracking']},
 {id:'hr',name:'HR & payroll',category:'People',icon:'people',tone:'',desc:'People processes, payroll setup, and employee compliance support as your team grows.',items:['Payroll setup','PF / ESI requirements','Employee onboarding support']}
];
